import Masonry from 'masonry-layout';
import imagesLoaded from 'imagesloaded';
import { useEffect, useRef } from 'react';
import PinCard from './PinCard';

const PinGrid = ({ pins }) => {
    const gridRef = useRef();

    useEffect(() => {
        const grid = gridRef.current;

        imagesLoaded(grid, () => {
            new Masonry(grid, {
                itemSelector: '.masonry-item',
                gutter: 20,
                fitWidth: true,
            });
        });
    }, [pins]);

    return (
        <div className="container py-4">
            <div ref={gridRef} className="d-flex flex-wrap justify-content-center">
                {pins.map(pin => (
                    <div key={pin.id} className="masonry-item" style={{ width: '250px', marginBottom: '20px' }}>
                        <PinCard pin={pin} />
                    </div>
                ))}
            </div>
        </div>
    );
};

export default PinGrid;
